<?php
if(!defined('ABSPATH'))exit;
function ff_nav_labels(){return ['home'=>'Home','software-development'=>'Software','web-development'=>'Websites','web-applications'=>'Automation','cybersecurity'=>'Cybersecurity','digital-marketing'=>'Marketing','portfolio'=>'Live Demos','about'=>'About','contact'=>'Contact'];}
function ff_labels(){return ff_nav_labels()+['privacy-policy'=>'Privacy Policy','terms-and-conditions'=>'Terms and Conditions'];}
function ff_titles(){return ['services'=>'Our Services','home'=>'Fera Foundry Home','software-development'=>'Software Development','web-development'=>'Website Development','web-applications'=>'Web Applications & Automation','cybersecurity'=>'Cybersecurity','digital-marketing'=>'Digital Marketing','portfolio'=>'Live Demos / Our Work','about'=>'About Fera Solution','contact'=>'Contact / Get a Quote','privacy-policy'=>'Privacy Policy','terms-and-conditions'=>'Terms and Conditions'];}
function ff_url($slug){if($slug==='home')return home_url('/');if($slug==='services'&&($id=ff_services_page_id()))return get_permalink($id);$ids=get_option('ff_pages',[]);return !empty($ids[$slug])?get_permalink($ids[$slug]):home_url('/'.$slug.'/');}
function ff_slug(){return is_front_page()?'home':(get_post_meta(get_queried_object_id(),'_ff_slug',true)?:'');}
function ff_inquiry_url(){return in_array(ff_slug(),['home','software-development','web-development','web-applications','cybersecurity','digital-marketing','portfolio','about','contact'],true)?'#inquiry':ff_url('contact').'#inquiry';}
function ff_content($slug){if($slug!=='services'&&!array_key_exists($slug,ff_labels()))return [];return json_decode(file_get_contents(get_theme_file_path('/content/'.$slug.'.json')),true)['content']??[];}
function ff_resolve($value){if(is_array($value))return array_map('ff_resolve',$value);if(!is_string($value))return $value;$value=str_replace('{{FERA_THEME_URL}}',get_template_directory_uri(),$value);foreach(ff_labels() as $slug=>$label)$value=str_replace('{{FERA_PAGE:'.$slug.'}}',ff_url($slug),$value);return $value;}
function ff_elementor_nodes($nodes){foreach($nodes as &$node){if(isset($node['id'])&&!preg_match('/^[a-f0-9]{7,8}$/iD',(string)$node['id']))$node['id']=substr(hash('sha256',(string)$node['id']),0,8);$node['elements']=ff_elementor_nodes($node['elements']??[]);}return $nodes;}
function ff_enable_elementor($id,$data){if(!defined('ELEMENTOR_VERSION'))return;$uploads=wp_upload_dir();if(!empty($uploads['error'])||!wp_mkdir_p($uploads['basedir'].'/elementor/css'))return new WP_Error('ff_uploads','Elementor CSS storage is unavailable. Check WordPress uploads permissions.');if(get_post_meta($id,'_elementor_edit_mode',true)==='builder')return;update_post_meta($id,'_elementor_data',wp_slash(wp_json_encode(ff_elementor_nodes($data))));update_post_meta($id,'_elementor_edit_mode','builder');update_post_meta($id,'_elementor_template_type','wp-page');update_post_meta($id,'_elementor_version',ELEMENTOR_VERSION);update_post_meta($id,'_elementor_page_settings',['hide_title'=>'yes']);update_post_meta($id,'_wp_page_template','default');}
function ff_install(){
 $ids=get_option('ff_pages',[]);if(!is_array($ids))$ids=[];
 foreach(ff_titles() as $slug=>$title){if($slug==='services')continue;if(!empty($ids[$slug])&&get_post_status($ids[$slug])&&get_post_status($ids[$slug])!=='trash'&&get_post_meta($ids[$slug],'_ff_slug',true)===$slug)continue;$id=wp_insert_post(['post_type'=>'page','post_title'=>$title,'post_name'=>$slug==='home'?'fera-foundry-home':$slug,'post_status'=>'publish'],true);if(is_wp_error($id))return $id;$ids[$slug]=$id;update_post_meta($id,'_ff_slug',$slug);update_option('ff_pages',$ids,false);}
 $demos=ff_install_demos();if(is_wp_error($demos))return $demos;
 foreach($ids as $slug=>$id){if(get_post_meta($id,'_ff_initialized',true))continue;$data=ff_resolve(ff_content($slug));update_post_meta($id,'_ff_content',wp_slash(wp_json_encode($data)));$enabled=ff_enable_elementor($id,$data);if(is_wp_error($enabled))return $enabled;update_post_meta($id,'_ff_initialized',1);}
 update_option('ff_installed',1,false);return $ids;
}
function ff_select_home(){if(!current_user_can('manage_options'))return new WP_Error('ff_permission','Administrator permission required.');$ids=ff_install();if(is_wp_error($ids))return $ids;if(!get_option('ff_previous_reading'))update_option('ff_previous_reading',['show_on_front'=>get_option('show_on_front'),'page_on_front'=>get_option('page_on_front'),'page_for_posts'=>get_option('page_for_posts')],false);update_option('show_on_front','page');update_option('page_on_front',$ids['home']);update_option('page_for_posts',0);return $ids;}
add_action('after_switch_theme',function(){ $result=ff_install();if(is_wp_error($result))update_option('ff_setup_error',$result->get_error_message(),false);else delete_option('ff_setup_error');flush_rewrite_rules(false); });
add_action('admin_post_ff_setup',function(){if(!current_user_can('manage_options'))wp_die('Not permitted.');check_admin_referer('ff_setup');$result=ff_select_home();if(is_wp_error($result))wp_die(esc_html($result->get_error_message()));foreach($result as $id){$enabled=ff_enable_elementor($id,json_decode(get_post_meta($id,'_ff_content',true),true)??[]);if(is_wp_error($enabled))wp_die(esc_html($enabled->get_error_message()));}delete_option('ff_setup_error');flush_rewrite_rules(false);wp_safe_redirect(admin_url('themes.php?page=fera-foundry'));exit;});
add_action('admin_post_ff_restore',function(){if(!current_user_can('manage_options'))wp_die('Not permitted.');check_admin_referer('ff_restore');foreach(get_option('ff_previous_reading',[]) as $key=>$value)if(in_array($key,['show_on_front','page_on_front','page_for_posts'],true))update_option($key,$value);wp_safe_redirect(admin_url('themes.php?page=fera-foundry'));exit;});
add_action('admin_notices',function(){if(!current_user_can('manage_options'))return;if($message=get_option('ff_setup_error'))echo '<div class="notice notice-error"><p>'.esc_html($message).'</p></div>';});
